class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> Optional[TreeNode]:
        inorder_index = {val: i for i, val in enumerate(inorder)}
        def build(pre_left: int, in_left: int, size: int) -> Optional[TreeNode]:
            if size == 0:
                return None
            root_val = preorder[pre_left]
            root = TreeNode(root_val)
            root_index = inorder_index[root_val]
            left_size = root_index - in_left
            right_size = size - left_size - 1
            root.left = build(pre_left + 1, in_left, left_size)
            root.right = build(pre_left + left_size + 1, root_index + 1, right_size)
            return root
        return build(0, 0, len(preorder))
```

